/* Halftone wordmark footer: the giant word is printed as a field of dots on a
   2D canvas. Dots part around the pointer on springs and warm in colour as
   they are pushed off their place; a click sends a shock ring through the word.
   Colours follow the Day / Night theme. Edit CFG to tune it. */
(function(){
var root=document.getElementById('footer');if(!root)return;
var canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d');if(!ctx)return;

var CFG={
  wordmark:'MIRWEB',   // the giant word
  dotGap:6,            // distance between dot centres (px)
  radius:80,           // how far the pointer pushes (px)
  crop:.2,             // how much of the cap height hangs below the bottom edge (0-0.6)
  grain:.5,            // print grain over everything (0-1)
  interactive:true,
  fontWeight:800,
  fontFamily:'"Inter Tight","Inter Variable","Inter","Helvetica Neue",Arial,system-ui,sans-serif'
};
var THEMES={
  dark:{background:'#0c0c0b',ink:'#f0f2f0',warm:'#f4ce15'},
  light:{background:'#e4e7e4',ink:'#222124',warm:'#c9a100'}
};

/* ---------- pure helpers ---------- */
function hex(h){var m=/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec((h||'').trim());if(!m)return null;var s=m[1].length===3?m[1].split('').map(function(c){return c+c}).join(''):m[1];return[parseInt(s.slice(0,2),16),parseInt(s.slice(2,4),16),parseInt(s.slice(4,6),16)]}
function dotRadius(cov,gap){var c=cov<0?0:cov>1?1:cov;return Math.sqrt(c)*gap*.56}
function step(x,y,vx,vy,hx,hy,px,py,r){
  var dx=x-px,dy=y-py,d2=dx*dx+dy*dy;
  if(r>0&&d2<r*r){var d=Math.sqrt(d2)+.001,f=(1-d/r)*2.6;vx+=dx/d*f;vy+=dy/d*f}
  vx=(vx+(hx-x)*.05)*.84;vy=(vy+(hy-y)*.05)*.84;
  return[x+vx,y+vy,vx,vy]
}
function warmth(x,y,hx,hy,span){var d=Math.hypot(x-hx,y-hy);return span>0?Math.min(1,d/span):0}
function fitSize(measured,width){return measured>0?width/measured*100:0}

/* ---------- state ---------- */
var colors=THEMES.dark,ink=[240,242,240],warm=[244,206,21];
var reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
var w=0,h=0,dpr=1,px=-1e5,py=-1e5,raf=0,visible=true,awake=true,ring={x:0,y:0,t:-1};
var dots=new Float32Array(0),count=0,grainTile=null; /* per dot: x,y,vx,vy,hx,hy,r */

function applyTheme(){
  colors=document.documentElement.getAttribute('data-theme')==='light'?THEMES.light:THEMES.dark;
  ink=hex(colors.ink)||ink;warm=hex(colors.warm)||warm;
  root.style.setProperty('--hwf-bg',colors.background);
  root.style.setProperty('--hwf-ink',colors.ink);
  wake();
}

function layout(){
  var rect=root.getBoundingClientRect();
  w=Math.max(1,Math.round(rect.width));h=Math.max(1,Math.round(rect.height));
  dpr=Math.min(window.devicePixelRatio||1,2);
  canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);

  /* set the word once, at a size that fills the width, on a 1x mask */
  var mask=document.createElement('canvas');mask.width=w;mask.height=h;
  var m=mask.getContext('2d',{willReadFrequently:true});if(!m)return;
  m.font=CFG.fontWeight+' 100px '+CFG.fontFamily;
  var word=CFG.wordmark||' ';
  var fit=fitSize(m.measureText(word).width,w*1.02);
  m.font=CFG.fontWeight+' '+fit+'px '+CFG.fontFamily;
  var box=m.measureText(word),cap=box.actualBoundingBoxAscent||fit*.72,c=Math.max(0,Math.min(.6,CFG.crop));
  m.fillStyle='#000';m.textBaseline='alphabetic';
  m.fillText(word,(w-box.width)/2,h+cap*c);
  var img=m.getImageData(0,0,w,h).data;

  var gap=Math.max(3,CFG.dotGap),cols=Math.ceil(w/gap),rows=Math.ceil(h/gap),tmp=[];
  for(var gy=0;gy<rows;gy++)for(var gx=0;gx<cols;gx++){
    var sum=0; /* coverage: average alpha over a 3x3 sample of the cell */
    for(var sy=0;sy<3;sy++)for(var sx=0;sx<3;sx++){
      var x=Math.min(w-1,Math.floor(gx*gap+(sx+.5)*gap/3)),y=Math.min(h-1,Math.floor(gy*gap+(sy+.5)*gap/3));
      sum+=img[(y*w+x)*4+3];
    }
    var cov=sum/(9*255);if(cov<.06)continue;
    var hx=gx*gap+gap/2,hy=gy*gap+gap/2;
    tmp.push(hx,hy,0,0,hx,hy,dotRadius(cov,gap));
  }
  dots=new Float32Array(tmp);count=tmp.length/7;

  /* a fixed tile of print grain, drawn once and laid over every frame */
  grainTile=document.createElement('canvas');grainTile.width=grainTile.height=256;
  var g=grainTile.getContext('2d');
  if(g){var id=g.createImageData(256,256);for(var i=0;i<id.data.length;i+=4){var v=Math.random()*255;id.data[i]=id.data[i+1]=id.data[i+2]=v;id.data[i+3]=Math.random()<.5?0:255}g.putImageData(id,0,0)}
  awake=true;
}

function draw(now){
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.fillStyle=colors.background;ctx.fillRect(0,0,w,h);
  var r=CFG.interactive&&!reduced?Math.max(0,CFG.radius):0;
  var ringAge=ring.t<0?1e9:now-ring.t,ringR=ringAge*.9,moving=false;
  for(var i=0;i<count;i++){
    var j=i*7,x=dots[j],y=dots[j+1],vx=dots[j+2],vy=dots[j+3],hx=dots[j+4],hy=dots[j+5];
    if(!reduced){
      if(ringAge<900){
        var dx=hx-ring.x,dy=hy-ring.y,d=Math.sqrt(dx*dx+dy*dy)+.001,band=1-Math.min(1,Math.abs(d-ringR)/26);
        if(band>0){var f=band*3.2*(1-ringAge/900);vx+=dx/d*f;vy+=dy/d*f}
      }
      var s=step(x,y,vx,vy,hx,hy,px,py,r);x=s[0];y=s[1];vx=s[2];vy=s[3];
      if(Math.abs(vx)+Math.abs(vy)>.02||Math.abs(x-hx)+Math.abs(y-hy)>.05)moving=true;
      else{x=hx;y=hy;vx=0;vy=0}
      dots[j]=x;dots[j+1]=y;dots[j+2]=vx;dots[j+3]=vy;
    }
    var k=warmth(x,y,hx,hy,28);
    ctx.fillStyle=k>.02?'rgb('+Math.round(ink[0]+(warm[0]-ink[0])*k)+','+Math.round(ink[1]+(warm[1]-ink[1])*k)+','+Math.round(ink[2]+(warm[2]-ink[2])*k)+')':colors.ink;
    ctx.beginPath();ctx.arc(x,y,dots[j+6],0,6.2832);ctx.fill();
  }
  if(grainTile&&CFG.grain>0){
    ctx.globalAlpha=Math.min(1,CFG.grain)*.09;ctx.globalCompositeOperation='overlay';
    var pat=ctx.createPattern(grainTile,'repeat');if(pat){ctx.fillStyle=pat;ctx.fillRect(0,0,w,h)}
    ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  }
  awake=moving||ringAge<900||px>-1e4; /* sleep once everything is home */
}
function loop(now){raf=0;if(!visible)return;draw(now);if(awake)raf=requestAnimationFrame(loop)}
function wake(){awake=true;if(!raf&&visible)raf=requestAnimationFrame(loop)}

function local(e){var b=canvas.getBoundingClientRect();return[e.clientX-b.left,e.clientY-b.top]}
root.addEventListener('pointermove',function(e){if(!CFG.interactive)return;var p=local(e);px=p[0];py=p[1];wake()});
root.addEventListener('pointerleave',function(){px=py=-1e5;wake()});
root.addEventListener('pointerdown',function(e){
  if(!CFG.interactive||reduced||e.target.closest('a,button'))return;
  var p=local(e);ring={x:p[0],y:p[1],t:performance.now()};wake();
});
root.querySelector('.hwf-up').addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});

applyTheme();layout();draw(performance.now());wake();
new ResizeObserver(function(){layout();wake()}).observe(root);
new IntersectionObserver(function(es){visible=es[0]?es[0].isIntersecting:true;if(visible)wake()}).observe(root);
new MutationObserver(applyTheme).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
/* when the web font lands late, re-set the word in its real face */
if(document.fonts){
  var relayout=function(){layout();wake()};
  if(document.fonts.load)document.fonts.load(CFG.fontWeight+' 100px "Inter Tight"').then(relayout,function(){});
  if(document.fonts.ready)document.fonts.ready.then(relayout);
}
})();

