/* "Let's talk" overlay + form, with a searchable country-code picker.
   Set ENDPOINT to your form-backend URL (JSON POST). While it is empty,
   the form opens the visitor's email app (mailto:) instead. */
(function(){
var tk=document.getElementById('talk'),fm=tk.querySelector('form'),stt=tk.querySelector('.st'),ENDPOINT='';
function openT(){if(MIRWEB.closeMenu)MIRWEB.closeMenu();tk.classList.add('open');document.body.classList.add('lock')}
function closeT(){closeList();tk.classList.remove('open');document.body.classList.remove('lock')}
document.querySelectorAll('[data-talk]').forEach(function(el){el.addEventListener('click',function(e){e.preventDefault();openT()})});
tk.querySelector('.back').addEventListener('click',closeT);

/* ---- country code picker ---- */
var btn=tk.querySelector('.cc-btn'),box=tk.querySelector('.cc-list'),search=box.querySelector('.cc-s'),ul=box.querySelector('ul'),ccIn=fm.elements.cc;
var cur=['Iran','98'];
function setCur(c){cur=c;btn.firstElementChild.textContent='+'+c[1];btn.setAttribute('title',c[0]);ccIn.value=c[1]}
function render(q){
  q=(q||'').trim().toLowerCase().replace(/^\+/,'');
  ul.textContent='';var shown=0;
  MIRWEB.countries.forEach(function(c){
    if(q&&c[0].toLowerCase().indexOf(q)<0&&c[1].indexOf(q)!==0)return;
    var li=document.createElement('li'),b=document.createElement('button');b.type='button';
    if(c[1]===cur[1]&&c[0]===cur[0])b.className='on';
    var n=document.createElement('span'),k=document.createElement('b');n.textContent=c[0];k.textContent='+'+c[1];b.appendChild(n);b.appendChild(k);
    b.addEventListener('click',function(){setCur(c);closeList();fm.elements.p.focus()});
    li.appendChild(b);ul.appendChild(li);shown++;
  });
  if(!shown){var e=document.createElement('li');e.className='no';e.textContent='No match';ul.appendChild(e)}
}
function openList(){box.hidden=false;btn.setAttribute('aria-expanded','true');search.value='';render('');search.focus();var on=ul.querySelector('.on');if(on)on.scrollIntoView({block:'center'})}
function closeList(){box.hidden=true;btn.setAttribute('aria-expanded','false')}
btn.addEventListener('click',function(){box.hidden?openList():closeList()});
search.addEventListener('input',function(){render(search.value)});
search.addEventListener('keydown',function(e){
  if(e.key==='Escape'){e.stopPropagation();closeList();btn.focus()}
  if(e.key==='Enter'){e.preventDefault();var f=ul.querySelector('button');if(f)f.click()}
});
document.addEventListener('pointerdown',function(e){if(!box.hidden&&!e.target.closest('.ph-row'))closeList()});
setCur(cur);

/* ---- submit ---- */
fm.addEventListener('submit',function(e){
  e.preventDefault();var f=fm.elements,phone=f.p.value.trim()?'+'+f.cc.value+' '+f.p.value.trim():'';
  var d={name:f.n.value,email:f.e.value,phone:phone,message:f.m.value};
  if(ENDPOINT){fetch(ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(function(r){if(!r.ok)throw 0;stt.textContent='Thank you, your message was sent.';fm.reset();setCur(['Iran','98'])}).catch(function(){stt.textContent='Something went wrong. Please try again.'})}
  else{location.href='mailto:hello@yourdomain.com?subject='+encodeURIComponent('Message from '+d.name)+'&body='+encodeURIComponent(d.message+'\n\n'+d.name+'\n'+d.email+'\n'+d.phone);stt.textContent='Opening your email app…'}
});
MIRWEB.openContact=openT;
MIRWEB.closeContact=closeT;
})();

/* Global keys: Escape closes any open overlay. Loads last. */
addEventListener('keydown',function(e){
  if(e.key==='Escape'){
    if(MIRWEB.closeProject)MIRWEB.closeProject();
    if(MIRWEB.closeContact)MIRWEB.closeContact();
    if(MIRWEB.closeMenu)MIRWEB.closeMenu();
  }
});
